jQuery(document).ready(function ($) {
        if (sessionStorage.getItem("bgls")) {
            $('#background').css('background-image', 'url(' + sessionStorage.getItem("bgls") + ')');
        } else {
            var images = [
                '/Content/images/layout/bg-login/01.jpg',
                '/Content/images/layout/bg-login/02.jpg',
                '/Content/images/layout/bg-login/03.jpg',
                '/Content/images/layout/bg-login/04.jpg',
                '/Content/images/layout/bg-login/05.jpg',
                '/Content/images/layout/bg-login/06.jpg',
                '/Content/images/layout/bg-login/07.jpg',
                '/Content/images/layout/bg-login/08.jpg'
            ];
            var key = Math.floor((Math.random() * images.length));
            var img = images[key];
            $('#background').css('background-image', 'url(' + img + ')');
            sessionStorage.getItem("bgls");
            sessionStorage.setItem("bgls", img);
        }

        $(this).bind("contextmenu", function (e) {
            e.preventDefault();
        });
        $.ajaxSetup({ cache: false });
    });
